return [ 'project-id-version' => 'fluid-checkout','mime-version' => '1.0','content-type' => 'text/plain; charset=utf-8','content-transfer-encoding' => '8bit','language-team' => 'Fluid Checkout','last-translator' => 'Fluid Checkout','pot-creation-date' => '2025-03-05 23:46+0000','report-msgid-bugs-to' => 'https://fluidcheckout.com/support','x-poedit-basepath' => '..','x-poedit-keywordslist' => '__;_e;_ex:1,2c;_n:1,2;_n_noop:1,2;_nx:1,2,4c;_nx_noop:1,2,3c;_x:1,2c;esc_attr__;esc_attr_e;esc_attr_x:1,2c;esc_html__;esc_html_e;esc_html_x:1,2c','x-poedit-searchpath-0' => '.','x-poedit-searchpathexcluded-0' => '*.js','x-poedit-sourcecharset' => 'UTF-8','plural-forms' => 'nplurals=2; plural=(n != 1);','messages' => ['WooCommerce' => 'WooCommerce','Go to Plugin Search' => 'Aneu a Cerca de connectors','Activate %s' => 'Activa %s','<strong>%1$s</strong> requires <strong>%2$s</strong> to be installed and activated. <a href="%4$s">%3$s</a>' => '<strong>%1$s</strong> requereix que <strong>%2$s</strong> estigui instal·lat i activat. <a href="%4$s">%3$s</a>','Enter your code here' => 'Introduïu el vostre codi aquí','Add %s' => 'Afegeix %s','Remove' => 'Eliminar','Order number and receipt will be sent to this email address.' => 'El número de comanda i el rebut s&#39;enviaran a aquesta adreça de correu electrònic.','Apartment, unit, building, floor, etc.' => 'Pis, unitat, edifici, pis, etc.','Shipping phone' => 'Telèfon d&#39;enviament','Only used for shipping-related questions.' => 'Només s&#39;utilitza per a preguntes relacionades amb l&#39;enviament.','Single step' => 'Un sol pas','Click to go to the order summary' => 'Feu clic per anar al resum de la comanda','Cart total:' => 'Total del carretó:','Proceed to %s' => 'Passeu a %s','Proceed to contact' => 'Passeu al contacte','Proceed to shipping' => 'Procedir a l&#39;enviament','Proceed to billing' => 'Passeu a la facturació','Proceed to payment' => 'Procedir al pagament','Shipping method' => 'Mètode d&#39;enviament','Additional notes' => 'Notes addicionals','Payment method' => 'Forma de pagament','Step %1$s of %2$s' => 'Pas %1$s de %2$s','Change: %s' => 'Canvi: %s','Not selected yet.' => 'Encara no seleccionat.','Same as shipping address' => 'Igual que l&#39;adreça d&#39;enviament','Same as billing address' => 'Igual que l&#39;adreça de facturació','Order summary' => 'Resum de la comanda','Edit cart' => 'Edita el carretó','Did you mean %s?' => 'Volíeu dir %s?','Change email address to: {suggestion-value}' => 'Canvia l&#39;adreça electrònica per: {suggestion-value}','This is a required field.' => 'Aquest és un camp obligatori.','This is not a valid email address.' => 'Aquesta adreça de correu electrònic no és vàlida.','This field does not match the related field value.' => 'Aquest camp no coincideix amb el valor del camp relacionat.','The CPF number "{cpf_number}" is invalid.' => 'El número CPF &quot;{cpf_number}&quot; no és vàlid.','The CNPJ number "{cnpj_number}" is invalid.' => 'El número CNPJ &quot;{cnpj_number}&quot; no és vàlid.','(Required)' => '(obligatori)','Checkout Header - Desktop' => 'Capçalera de pagament - Escriptori','Display widgets on the checkout header for large screens. Only displayed if using the plugin\'s checkout header.' => 'Mostra ginys a la capçalera de pagament per a pantalles grans. Només es mostra si s&#39;utilitza la capçalera de pagament del connector.','Checkout Header - Mobile' => 'Capçalera de pagament: mòbil','Display widgets below the checkout header for mobile devices. Only displayed if using the plugin\'s checkout header.' => 'Mostra els widgets a sota de la capçalera de pagament per a dispositius mòbils. Només es mostra si s&#39;utilitza la capçalera de pagament del connector.','Checkout Sidebar' => 'Barra lateral de compra','Display widgets on the checkout sidebar after the order summary.' => 'Mostra els widgets a la barra lateral de pagament després del resum de la comanda.','Checkout Order Summary' => 'Resum de la comanda de pagament','Display widgets inside the order summary at the checkout page.' => 'Mostra els widgets dins del resum de la comanda a la pàgina de pagament.','Checkout Below Place Order' => 'Fes la compra a sota Fes la comanda','Display widgets below the place order button at the checkout page.' => 'Mostra els widgets a sota del botó de fer la comanda a la pàgina de pagament.','Checkout Footer' => 'Peu de pàgina de compra','Display widgets on the checkout footer. Only displayed if using the plugin\'s checkout footer.' => 'Mostra els ginys al peu de la compra. Només es mostra si s&#39;utilitza el peu de pàgina de pagament del connector.','Classic' => 'Clàssic','Boxed' => 'En caixa','Split' => 'Dividir','Minimalist' => 'Minimalista','Fluid Checkout and Delivery Date plugins by CodeRockz' => 'Complements Fluid Checkout i Data de lliurament de CodeRockz','<p>We detected that you are using the plugins Delivery & Pickup Date Time for WooCommerce (free and PRO) by CodeRockz. Integration with these plugins have been moved to Fluid Checkout PRO.</p>' => '<p>Hem detectat que estàs utilitzant els connectors Data de lliurament i hora de recollida per a WooCommerce (gratuïts i PRO) de CodeRockz. La integració amb aquests connectors s&#39;ha mogut a Fluid Checkout PRO.</p>','Upgrade to PRO' => 'Actualitza a PRO','Fluid Checkout database updated successfully' => 'La base de dades de Fluid Checkout s&#39;ha actualitzat correctament','The database changes where applied successfully.' => 'La base de dades canvia quan s&#39;aplica correctament.','Dismiss' => 'Descartar','Fluid Checkout database update' => 'Actualització de la base de dades de Fluid Checkout','Some changes to the database are required. As with any update, we recommend you to <strong>take a full backup of your website before proceeding</strong>.' => 'Calen alguns canvis a la base de dades. Com amb qualsevol actualització, us recomanem que <strong>feu una còpia de seguretat completa del vostre lloc web abans de continuar</strong> .','Update database' => 'Actualitzar la base de dades','Fluid Checkout is not compatible with the Divi Builder checkout layout' => 'Fluid Checkout no és compatible amb el disseny de pagament de Divi Builder','<p>Fluid Checkout needs the classic WooCommerce shortcode-based checkout form to work. When using the Divi Builder to customize the look and feel of the checkout page, the classic shortcodes are replaced with custom widgets from the Divi Builder for each part of the checkout page. These custom widgets are not compatible with Fluid Checkout.</p><p>Please edit your checkout page replacing the Divi Builder widgets with the a text widget containing the shortcode <code>[woocommerce_checkout]</code>.</p>' => '<p>Fluid Checkout necessita el formulari de pagament clàssic basat en codi curt de WooCommerce per funcionar. Quan utilitzeu el Divi Builder per personalitzar l&#39;aspecte de la pàgina de pagament, els codis curts clàssics es substitueixen per ginys personalitzats del Divi Builder per a cada part de la pàgina de pagament. Aquests ginys personalitzats no són compatibles amb Fluid Checkout.</p><p> Editeu la vostra pàgina de pagament substituint els ginys de Divi Builder per un widget de text que conté el codi curt <code>[woocommerce_checkout]</code> .</p>','Edit the checkout page' => 'Editeu la pàgina de pagament','Read the documentation.' => 'Llegeix la documentació.','Germanized PRO multistep checkout feature needs to be disabled when using Fluid Checkout' => 'Cal desactivar la funció de pagament de diversos passos Germanized PRO quan utilitzeu Fluid Checkout','When using Fluid Checkout, the multistep feature from the Germanized PRO plugin becomes unnecessary and can cause <strong>critical errors while processing new orders</strong>. Please disable the Germanized PRO multistep checkout feature in the plugin settings.' => 'Quan s&#39;utilitza Fluid Checkout, la funció de diversos passos del connector Germanized PRO es fa innecessària i pot provocar <strong>errors crítics durant el processament de noves comandes</strong> . Si us plau, desactiveu la funció de pagament de diversos passos Germanized PRO a la configuració del connector.','Go to Germanized settings' => 'Aneu a la configuració germanitzada','Thanks for choosing Fluid Checkout!' => 'Gràcies per triar Fluid Checkout!','You have been using the plugin for a while now. How do you like it so far? <br>Please give us a quick rating, we appreciate every bit of feedback and it encourages us to keep improving the plugin :)' => 'Fa temps que feu servir el connector. Com t&#39;agrada fins ara?<br> Si us plau, doneu-nos una puntuació ràpida, agraïm tots els comentaris i ens anima a seguir millorant el connector :)','Rate the plugin' => 'Valoreu el connector','I need help!' => 'Necessito ajuda!','Some features of WooCommerce Checkout Manager by Quadlayers might not work as expected when using it with Fluid Checkout. Read <a href="%s">our documentation</a> for more information and alternative solutions.' => 'És possible que algunes funcions de WooCommerce Checkout Manager de Quadlayers no funcionin com s&#39;esperava quan l&#39;utilitzeu amb Fluid Checkout. Llegiu <a href="%s">la nostra documentació</a> per obtenir més informació i solucions alternatives.','Read documentation' => 'Llegeix la documentació','Don\'t show this again' => 'No tornis a mostrar això','Fluid Checkout PRO' => 'Fluid Checkout PRO','More design templates' => 'Més plantilles de disseny','Optimized cart page' => 'Pàgina optimitzada del carretó','Optimized order received / thank you page' => 'Comanda optimitzada rebuda / pàgina d&#39;agraïment','Edit cart contents at checkout page' => 'Editeu el contingut del carretó a la pàgina de pagament','Account matching / user matching' => 'Concordança de comptes/concordança d&#39;usuaris','Trust symbols on the cart and thank you pages' => 'Símbols de confiança al carretó i pàgines d&#39;agraïment','More positions for the coupon code on the checkout page' => 'Més posicions per al codi de cupó a la pàgina de pagament','International phone numbers' => 'Números de telèfon internacionals','Gift messages and packing slips' => 'Missatges de regal i albarans','Local pickup and in-store collection' => 'Recollida local i recollida a la botiga','EU-VAT Assistant' => 'Assistent UE-IVA','I already have it – Hide this offer' => 'Ja ho tinc: amaga aquesta oferta','Activated' => 'Activat','Address book' => 'Llibreta d&#39;adreces','Select an image' => 'Seleccioneu una imatge','Cart layout' => 'Distribució del carro','Cart optimizations' => 'Optimitzacions del carretó','Enable cart page optimizations' => 'Activa les optimitzacions de la pàgina del carretó','Header and footer template' => 'Plantilla de capçalera i peu de pàgina','Controls whether to use the distraction free page header and footer or keep the currently active theme\'s header and footer.' => 'Controla si s&#39;utilitza la capçalera i el peu de pàgina sense distraccions o si es manté la capçalera i el peu de pàgina del tema actualment actiu.','Distraction free header and footer' => 'Capçalera i peu de pàgina sense distraccions','Theme\'s header and footer' => 'Capçalera i peu de pàgina del tema','Cart elements' => 'Elements del carro','Make the order summary stay visible on the cart page while scrolling' => 'Feu que el resum de la comanda es mantingui visible a la pàgina del carretó mentre us desplaceu','Coupon codes' => 'Codis de cupó','Hidden' => 'Ocult','Before the cart items section' => 'Abans de la secció d&#39;articles del carretó','Inside the cart items section' => 'Dins de la secció d&#39;articles del carretó','After the cart items section' => 'Després de la secció d&#39;articles del carretó','Before the shipping section' => 'Abans de la secció d&#39;enviament','After the shipping section' => 'Després de la secció d&#39;enviament','Before the order summary' => 'Abans del resum de la comanda','Inside the order summary' => 'Dins del resum de la comanda','Before the order totals' => 'Abans del total de la comanda','After the order totals' => 'Després dels totals de la comanda','After the order summary' => 'Després del resum de la comanda','Shipping' => 'Enviament','Select position where to display the shipping costs and calculator on the cart page.' => 'Seleccioneu la posició on mostrar els costos d&#39;enviament i la calculadora a la pàgina del carretó.','Display as a cart section' => 'Mostra com a secció de carro','Cross-sells' => 'Vendes creuades','Select position where to display the cross-sells section on the cart page.' => 'Seleccioneu la posició on voleu mostrar la secció de vendes creuades a la pàgina del carretó.','Before the cart actions' => 'Abans de les accions del carro','After the cart actions' => 'Després de les accions del carro','Layout of cross-sell items on the cart page.' => 'Disseny dels articles de venda creuada a la pàgina del carretó.','Optimized horizontal cross-sells layout' => 'Disseny de venda creuada horitzontal optimitzat','Theme\'s cross-sells layout' => 'Disseny de vendes creuades del tema','Number of cross-sell items to display on the cart page' => 'Nombre d&#39;articles de venda creuada per mostrar a la pàgina del carretó','Add widget areas to the cart page' => 'Afegiu àrees de widget a la pàgina del carretó','These widget areas are used to add trust symbols and trust badges on the cart page.' => 'Aquestes àrees de widget s&#39;utilitzen per afegir símbols de confiança i insígnies de confiança a la pàgina del carretó.','Checkout' => 'Pagament','Checkout layout' => 'Disseny de la caixa','Design template' => 'Plantilla de disseny','Dark mode' => 'Mode fosc','Enable dark mode' => 'Activa el mode fosc','Logo image' => 'Imatge del logotip','Choose an image to be displayed on the checkout page header. Only applies when using the distraction free header and footer.' => 'Trieu una imatge que es mostrarà a la capçalera de la pàgina de pagament. Només s&#39;aplica quan s&#39;utilitza la capçalera i el peu de pàgina sense distraccions.','Header background color' => 'Color de fons de la capçalera','Choose a background color for the checkout page header. Only applies when using the distraction free header and footer.' => 'Trieu un color de fons per a la capçalera de la pàgina de pagament. Només s&#39;aplica quan s&#39;utilitza la capçalera i el peu de pàgina sense distraccions.','HTML color value. ie: #f3f3f3' => 'Valor de color HTML. és a dir: #f3f3f3','Page background color' => 'Color de fons de la pàgina','Choose a background color for the checkout page. Color is applied to the <em>body</em> element.' => 'Trieu un color de fons per a la pàgina de pagament. El color s&#39;aplica a l&#39;element <em>del cos</em> .','Footer background color' => 'Color de fons del peu de pàgina','Choose a background color for the checkout page footer. Only applies when using the distraction free header and footer.' => 'Trieu un color de fons per al peu de pàgina de pagament. Només s&#39;aplica quan s&#39;utilitza la capçalera i el peu de pàgina sense distraccions.','Progress bar' => 'Barra de progrés','Display the checkout progress bar when using multi-step checkout layout' => 'Mostra la barra de progrés de la compra quan utilitzeu el disseny de pagament de diversos passos','Make the checkout progress bar stay visible while scrolling' => 'Feu que la barra de progrés de la compra sigui visible mentre us desplaceu','Express checkout' => 'Pagament exprés','Enable the express checkout section' => 'Activa la secció de pagament exprés','Displays the express checkout section at checkout when supported payment gateways have this feature enabled.' => 'Mostra la secció de pagament exprés a l&#39;hora de pagar quan les passarel·les de pagament admeses tenen aquesta funció activada.','Display express checkout buttons in one line for larger screens' => 'Mostra els botons de pagament ràpid en una línia per a pantalles més grans','Ignore additional checkout required fields when paying with a compatible express checkout payment gateway' => 'Ignoreu els camps obligatoris de pagament addicionals quan pagueu amb una passarel·la de pagament de pagament ràpid compatible','Make the order summary stay visible while scrolling' => 'Feu que el resum de la comanda es mantingui visible mentre us desplaceu','Choose a background color for the order summary section.' => 'Trieu un color de fons per a la secció de resum de la comanda.','Highlight the order totals row in the order summary table' => 'Ressalteu la fila de totals de la comanda a la taula de resum de la comanda','Most useful when the order summary section does not have a highlighted background color. Might also apply to the Cart, Order Received and View Order pages when using Fluid Checkout PRO.' => 'Més útil quan la secció de resum de la comanda no té un color de fons ressaltat. També es pot aplicar a les pàgines Cistell, Comanda rebuda i Veure comanda quan utilitzeu Fluid Checkout PRO.','Action link on the order summary at checkout.' => 'Enllaç d&#39;acció al resum de la comanda a la compra.','Edit cart link' => 'Edita l&#39;enllaç del carretó','Cart items count' => 'Els articles del carretó compten','Link to shop page' => 'Enllaç a la pàgina de la botiga','Cart items' => 'Articles del carretó','Hide cart items errors at the checkout page' => 'Amaga els errors dels articles del carretó a la pàgina de pagament','Do not display the cart items errors message at the top of the checkout page. When submitting the checkout form to complete the purchase, these error messages will always be displayed.' => 'No mostri el missatge d&#39;error d&#39;articles del carretó a la part superior de la pàgina de pagament. Quan envieu el formulari de pagament per completar la compra, aquests missatges d&#39;error sempre es mostraran.','Place order' => 'Fes la comanda','Define the position to display "Place order" and terms checkbox section.' => 'Definiu la posició per mostrar la secció &quot;Fes la comanda&quot; i la casella de selecció de termes.','Some options might not be compatible with some plugins and themes.' => 'És possible que algunes opcions no siguin compatibles amb alguns complements i temes.','Below the payment section' => 'A sota de la secció de pagament','Below the order summary' => 'A sota del resum de la comanda','Both below the payment section and the order summary' => 'Tant a sota de la secció de pagament com al resum de la comanda','Add widget areas to the checkout page' => 'Afegiu àrees de widget a la pàgina de pagament','These widget areas are used to add trust symbols and trust badges on the checkout page.' => 'Aquestes àrees de widget s&#39;utilitzen per afegir símbols de confiança i insígnies de confiança a la pàgina de pagament.','Display the coupon codes section title' => 'Mostra el títol de la secció de codis de cupó','Select position where to display the coupon codes section on the checkout page.' => 'Seleccioneu la posició on voleu mostrar la secció de codis de cupó a la pàgina de pagament.','Before the checkout steps' => 'Abans dels passos de la compra','As a substep before payment methods' => 'Com a subpas abans dels mètodes de pagament','As a substep after payment methods' => 'Com a subpas després dels mètodes de pagament','Default button style' => 'Estil de botó predeterminat','"Add" link button' => 'Botó d&#39;enllaç &quot;Afegeix&quot;.','Checkout fields' => 'Camps de pagament','Optional fields' => 'Camps opcionals','Hide optional fields behind a link button' => 'Amaga els camps opcionals darrere d&#39;un botó d&#39;enllaç','It is recommended to keep this option checked to reduce the number of open input fields, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">read the research</a>.' => 'Es recomana mantenir aquesta opció marcada per reduir el nombre de camps d&#39;entrada oberts, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#1-address-line-2--company-name-can-safely-be-collapsed-behind-a-link" target="_blank">llegiu la recerca</a> .','Do not hide "Address line 2" fields behind a link button' => 'No amagueu els camps &quot;Línia d&#39;adreça 2&quot; darrere d&#39;un botó d&#39;enllaç','Recommended only when most customers actually need the "Address line 2" field, or when getting the right shipping address is crucial (ie. if delivering food and other perishable products).' => 'Només es recomana quan la majoria dels clients realment necessiten el camp &quot;Línia d&#39;adreça 2&quot; o quan és crucial obtenir l&#39;adreça d&#39;enviament correcta (és a dir, si es lliura menjar i altres productes peribles).','Billing address' => 'Adreça de facturació','Select position where to display the billing address section on the checkout page.' => 'Seleccioneu la posició on voleu mostrar la secció d&#39;adreça de facturació a la pàgina de pagament.','As a step before shipping' => 'Com a pas abans de l&#39;enviament','As a sub-step before the shipping address section' => 'Com a subpas abans de la secció d&#39;adreça d&#39;enviament','As a sub-step after the shipping address section' => 'Com a subpas després de la secció d&#39;adreça d&#39;enviament','As a step after shipping' => 'Com a pas després de l&#39;enviament','As a sub-step before the payment section' => 'Com a subpas abans de la secció de pagament','Force billing and shipping addresses to the same (single section)' => 'Força les adreces de facturació i enviament al mateix (secció única)','Checkbox for "Same as shipping/billing address" checked by default' => 'La casella de selecció &quot;Igual que l&#39;adreça d&#39;enviament/facturació&quot; està marcada de manera predeterminada','The checkbox "Same as shiping address" will start as checked by default when the shipping address section is displayed first. <br>The checkbox "Same as billing address" will start as checked by default when the billing address section is displayed first. <br> It is recommended to leave this option checked as to significantly reduce the number of open input fields at checkout, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">read the research</a>.' => 'La casella de selecció &quot;Igual que l&#39;adreça d&#39;enviament&quot; començarà com a marcada per defecte quan es mostri primer la secció d&#39;adreça d&#39;enviament.<br> La casella de selecció &quot;Igual que l&#39;adreça de facturació&quot; començarà tal com està marcada per defecte quan es mostri primer la secció d&#39;adreça de facturació.<br> Es recomana deixar aquesta opció marcada per reduir significativament el nombre de camps d&#39;entrada oberts a la compra, <a href="https://baymard.com/blog/checkout-flow-average-form-fields#3-default-billing--shipping-and-hide-the-fields-entirely" target="_blank">llegiu la investigació</a> .','Highlight the billing address section in the checkout form' => 'Ressalteu la secció d&#39;adreça de facturació al formulari de pagament','Shipping address' => 'Adreça d&#39;enviament','Highlight the shipping address section in the checkout form' => 'Ressalteu la secció d&#39;adreça d&#39;enviament al formulari de pagament','Shipping methods' => 'Mètodes d&#39;enviament','Choose in which position to display the shipping methods section.' => 'Trieu en quina posició voleu mostrar la secció de mètodes d&#39;enviament.','Before shipping address' => 'Abans de l&#39;adreça d&#39;enviament','After shipping address' => 'Després de l&#39;adreça d&#39;enviament','Local pickup' => 'Recollida local','Removes shipping address section when a local pickup shipping method is selected.' => 'Elimina la secció d&#39;adreça d&#39;enviament quan es selecciona un mètode d&#39;enviament de recollida local.','Replaces the shipping address with the pickup point location when a local pickup shipping method is selected.' => 'Substitueix l&#39;adreça d&#39;enviament per la ubicació del punt de recollida quan es selecciona un mètode d&#39;enviament de recollida local.','Choose which address to save as the shipping address for local pickup orders.' => 'Trieu quina adreça voleu desar com a adreça d&#39;enviament per a les comandes de recollida local.','Save the selected pickup location' => 'Desa el lloc de recollida seleccionat','Save same as the billing address' => 'Desa el mateix que l&#39;adreça de facturació','Do not save any shipping address' => 'No deseu cap adreça d&#39;enviament','Company name field for shipping address' => 'Camp de nom de l&#39;empresa per a l&#39;adreça d&#39;enviament','Change visibility for the company name field for the shipping address section on the checkout form.' => 'Canvieu la visibilitat del camp del nom de l&#39;empresa per a la secció d&#39;adreça d&#39;enviament del formulari de pagament.','If field is set as "optional", which is the default visibility state, no changes will be applied to let other plugins apply any changes they need.' => 'Si el camp s&#39;estableix com a &quot;opcional&quot;, que és l&#39;estat de visibilitat predeterminat, no s&#39;aplicaran canvis per permetre que altres connectors apliquen els canvis que necessiten.','Hidden (remove field)' => 'Ocult (elimina el camp)','Optional' => 'Opcional','Required' => 'Obligatori','Add shipping phone field to the checkout form.' => 'Afegiu el camp del telèfon d&#39;enviament al formulari de pagament.','Choose in which step to display the shipping phone field.' => 'Trieu en quin pas voleu mostrar el camp del telèfon d&#39;enviament.','Contact step' => 'Pas de contacte','Billing phone' => 'Telèfon de facturació','Add billing phone field to the checkout form.' => 'Afegiu el camp del telèfon de facturació al formulari de pagament.','Choose in which step to display the billing phone field.' => 'Trieu en quin pas voleu mostrar el camp del telèfon de facturació.','Show country code beside the flag' => 'Mostra el codi del país al costat de la bandera','Show an example of a valid phone number inside phone fields' => 'Mostra un exemple de número de telèfon vàlid dins dels camps de telèfon','Do not change placeholders' => 'No canvieu els marcadors de posició','Show if not defined' => 'Mostra si no està definit','Always show' => 'Mostra sempre','Order notes' => 'Notes de comanda','Define the visibility of the additional order notes field.' => 'Definiu la visibilitat del camp de notes de comanda addicionals.','Gift options' => 'Opcions de regal','Allow customers to add a gift message and other gift related options to the order.' => 'Permet als clients afegir un missatge de regal i altres opcions relacionades amb el regal a la comanda.','Display the gift message as part of the order details table instead of a separate section' => 'Mostra el missatge del regal com a part de la taula de detalls de la comanda en lloc d&#39;una secció separada','This option affects the order confirmation page (thank you page) and order details on account pages, emails and packing slips.' => 'Aquesta opció afecta la pàgina de confirmació de la comanda (pàgina d&#39;agraïment) i els detalls de la comanda a les pàgines del compte, correus electrònics i albarans.','Account matching' => 'Concordança del compte','Enable the account matching feature' => 'Activa la funció de concordança de comptes','Associate the guest customer\'s orders with their existing account when an account already exists with the customer\'s contact details.' => 'Associa les comandes del client convidat amb el seu compte existent quan ja existeix un compte amb les dades de contacte del client.','Display message when an account exists with the email address provided' => 'Mostra el missatge quan existeix un compte amb l&#39;adreça de correu electrònic proporcionada','Replaces the account creation fields with a notification and option to log in. In some contexts, it might be recommended to leave this option disabled to protect the privacy of customers.' => 'Substitueix els camps de creació del compte per una notificació i una opció per iniciar sessió. En alguns contextos, es recomana deixar aquesta opció desactivada per protegir la privadesa dels clients.','Dashboard' => 'Tauler de control','Integrations' => 'Integracions','License keys' => 'Claus de llicència','Visit our website for more information about our plugins and add-ons.' => 'Visiteu el nostre lloc web per obtenir més informació sobre els nostres complements i complements.','Order pay page' => 'Pàgina de pagament de la comanda','Order pay' => 'Ordre de pagament','Enable order pay page optimizations' => 'Activa les optimitzacions de la pàgina de pagament de la comanda','Changes the layout of order pay page for existing orders pending payment from the customer.' => 'Canvia el disseny de la pàgina de pagament de la comanda per a les comandes existents pendents de pagament del client.','Add widget areas to the order pay page' => 'Afegiu àrees de widget a la pàgina de pagament de la comanda','These widget areas are used to add trust symbols and trust badges on the order pay page.' => 'Aquestes àrees de giny s&#39;utilitzen per afegir símbols de confiança i insígnies de confiança a la pàgina de pagament de la comanda.','Thank you page & order details layout' => 'Gràcies pàgina i disseny de detalls de la comanda','Order details optimizations' => 'Optimitzacions de detalls de comanda','Enable thank you page and order details optimizations' => 'Activa les optimitzacions de la pàgina d&#39;agraïment i dels detalls de la comanda','Changes the layout of order details on the thank you page and account pages.' => 'Canvia la disposició dels detalls de la comanda a la pàgina d&#39;agraïment i a les pàgines del compte.','Enable order details customizations on email notifications' => 'Activa les personalitzacions dels detalls de la comanda a les notificacions per correu electrònic','Display new sections and change order of sections on email notifications. Styles of order details on email notifications remain unchanged.' => 'Mostra les seccions noves i canvia l&#39;ordre de les seccions a les notificacions per correu electrònic. Els estils dels detalls de la comanda a les notificacions per correu electrònic es mantenen sense canvis.','Thank you page' => 'Gràcies pàgina','These options affect the thank you page, also known as order received or order confirmation pages.' => 'Aquestes opcions afecten la pàgina d&#39;agraïment, també coneguda com a pàgina de comanda rebuda o de confirmació de comanda.','Order details layout' => 'Disseny de detalls de la comanda','Display the order details with wide layout on the thank you page' => 'Mostra els detalls de la comanda amb un disseny ampli a la pàgina d&#39;agraïment','Add widget areas to the thank you page' => 'Afegiu àrees de widget a la pàgina d&#39;agraïment','These widget areas are used to add trust symbols and trust badges on the thank you page.' => 'Aquestes àrees de widget s&#39;utilitzen per afegir símbols de confiança i insígnies de confiança a la pàgina d&#39;agraïment.','Order actions' => 'Ordenar accions','Choose in which position to display the order actions.' => 'Trieu en quina posició voleu mostrar les accions de comanda.','Inside the order overview' => 'Dins de la visió general de la comanda','After the order overview' => 'Després de la visió general de la comanda','After order sections' => 'Després de les seccions de comanda','Order status' => 'Estat de la comanda','Display the order status progress bar' => 'Mostra la barra de progrés d&#39;estat de la comanda','Choose in which position to display the section.' => 'Trieu en quina posició voleu mostrar la secció.','After the order overview and payment instructions' => 'Després de la visió general de la comanda i les instruccions de pagament','Before the order items section' => 'Abans de la secció d&#39;articles de comanda','Inside the order items section' => 'Dins de la secció d&#39;articles de comanda','After the order items section' => 'Després de la secció d&#39;articles de comanda','On the sidebar' => 'A la barra lateral','Order downloads' => 'Encarregueu descàrregues','Gift message' => 'Missatge de regal','Tools' => 'Eines','Troubleshooting' => 'Resolució de problemes','Debug options' => 'Opcions de depuració','Debug mode' => 'Mode de depuració','Using debug mode affects the website performance. Only use this option while troubleshooting.' => 'L&#39;ús del mode de depuració afecta el rendiment del lloc web. Utilitzeu aquesta opció només durant la resolució de problemes.','Load unminified assets' => 'Carregueu actius no minificats','Enhanced select fields' => 'Camps de selecció millorats','Fix automatic zoom-in on form fields' => 'Corregiu l&#39;ampliació automàtica dels camps del formulari','Set <code>font-size</code> inside form fields to 16px' => 'Estableix <code>font-size</code> dins dels camps del formulari a 16 píxels','Fluid Checkout' => 'Checkout de fluids','Settings' => 'Configuració','Support' => 'Suport','<a target="_blank" href="%s">Upgrade to PRO</a> to unlock more options.' => '<a target="_blank" href="%s">Actualitza a PRO</a> per desbloquejar més opcions.','(PRO)' => '(PRO)','(experimental)' => '(experimental)','Please verify your phone number.' => 'Verifiqueu el vostre número de telèfon.','The Bluehost Plugin' => 'El connector Bluehost','Custom fields' => 'Camps personalitzats','Enable custom shipping email field' => 'Activa el camp de correu electrònic d&#39;enviament personalitzat','When enabled, the shipping email field from the Bluehost plugin will be added to the checkout form.' => 'Quan estigui activat, el camp de correu electrònic d&#39;enviament del connector Bluehost s&#39;afegirà al formulari de pagament.','Captcha Pro by BestWebSoft' => 'Captcha Pro de BestWebSoft','Captcha position' => 'Posició captcha','Define the position to display the captcha section. Some positions might not work depending on the captcha type chosen.' => 'Definiu la posició per mostrar la secció captcha. És possible que algunes posicions no funcionin segons el tipus de captcha escollit.','Selecting a pickup point is required before proceeding.' => 'Cal seleccionar un punt de recollida abans de continuar.','Pickup point' => 'Punt de recollida','Pickup point not selected yet.' => 'El punt de recollida encara no s&#39;ha seleccionat.','Pickup point:' => 'Punt de recollida:','Mailchimp for WooCommerce' => 'Mailchimp per a WooCommerce','Subscribe checkbox' => 'casella de selecció Subscriu-te','Override the position for the subscribe checkbox on the checkout page and always display it on the contact step' => 'Anul·leu la posició de la casella de selecció de subscripció a la pàgina de pagament i visualitzeu-la sempre al pas de contacte','Before Shipping Address' => 'Abans de l&#39;adreça d&#39;enviament','(originally "%s")' => '(originalment &quot;%s&quot;)','After Shipping Address' => 'Després de l&#39;adreça d&#39;enviament','Selecting a collection point is required when shipping with FermoPoint.' => 'Cal seleccionar un punt de recollida quan s&#39;envia amb FermoPoint.','If checked informs typos in email to users. (This feature has been disabled because Fluid Checkout offers the feature. Changes to this option will not take effect)' => 'Si està marcat, s&#39;informarà d&#39;errors ortogràfics al correu electrònic als usuaris. (Aquesta funció s&#39;ha desactivat perquè Fluid Checkout ofereix la funció. Els canvis a aquesta opció no tindran efecte)','Enable Mail Check: (disabled feature)' => 'Activa la comprovació de correu: (funció desactivada)','Carrier:' => 'Transportista:','Sendinblue - WooCommerce Email Marketing' => 'Sendinblue - Màrqueting per correu electrònic de WooCommerce','Sign up checkbox position' => 'Posició de la casella de selecció de registre','Move the sign up checkbox to the contact step' => 'Mou la casella de selecció de registre al pas de contacte','When enabled, the checkbox will be moved to the contact step independently of the display location defined in the Sendinblue plugin settings.' => 'Quan estigui activat, la casella de selecció es mourà al pas de contacte independentment de la ubicació de visualització definida a la configuració del connector Sendinblue.','Theme Betheme' => 'Tema Betheme','Checkout progress' => 'Progrés de la compra','Output the checkout steps section from Betheme on the checkout, cart and order received pages.' => 'Envieu la secció de passos de compra de Betheme a les pàgines de compra, carretó i comandes rebudes.','Theme Fennik' => 'Tema Fennik','Breadcrumbs' => 'Pa ratllat','Output the breadcrumbs section from the Fennik theme when using Fluid Checkout header and footer.' => 'Emet la secció de mitges de pa del tema Fennik quan utilitzeu la capçalera i el peu de pàgina de Fluid Checkout.','Theme Go' => 'Tema Go','My account layout' => 'Disseny del meu compte','Enable wide layout on "My account" page.' => 'Activa el disseny ampli a la pàgina &quot;El meu compte&quot;.','Theme Impreza' => 'Tema Impreza','Header' => 'Capçalera','Spacing for site header at the checkout page (in pixels)' => 'Espaiat per a la capçalera del lloc a la pàgina de pagament (en píxels)','Only applicable when using the Impreza theme header at the checkout page.' => 'Només s&#39;aplica quan s&#39;utilitza la capçalera del tema Impreza a la pàgina de pagament.','Theme Kapee' => 'Tema Kapee','Output the checkout steps section from the Kapee theme on the checkout, cart and order received pages.' => 'Escriviu la secció de passos de compra del tema Kapee a les pàgines de compra, carretó i comandes rebudes.','Theme Porto' => 'Tema Porto','Output the checkout steps section from the Porto theme on the checkout, cart and order received pages.' => 'Escriviu la secció de passos de compra del tema Porto a les pàgines de compra, carretó i comandes rebudes.','Theme Pressmart' => 'Tema Pressmart','Output the checkout steps section from the Pressmart theme on the checkout, cart and order received pages.' => 'Escriviu la secció de passos de pagament del tema Pressmart a les pàgines de pagament, carretó i comandes rebudes.','Theme The Gem' => 'Tema La joia','Output the checkout steps section from The Gem theme when using Fluid Checkout header and footer.' => 'Escriviu la secció de passos de compra del tema The Gem quan feu servir la capçalera i el peu de pàgina de Fluid Checkout.','Theme Woodmart' => 'Tema Woodmart','Output the checkout steps section from the Woodmart theme when using Fluid Checkout header and footer.' => 'Escriviu la secció de passos de pagament del tema Woodmart quan feu servir la capçalera i el peu de pàgina de Fluid Checkout.','Checkout options' => 'Opcions de pagament','Disable the theme checkout options' => 'Desactiveu les opcions de compra del tema','The options display product image, quantity field, remove button and link to product page added by the theme are disabled by default.' => 'Les opcions mostren la imatge del producte, el camp de quantitat, el botó d&#39;eliminació i l&#39;enllaç a la pàgina del producte afegit pel tema estan desactivats de manera predeterminada.','Theme Atomion' => 'Tema Atomion','Order progress' => 'Progrés de la comanda','Display order progress from the theme' => 'Mostra el progrés de la comanda des del tema','Display the form field labels visible on the page' => 'Mostra les etiquetes dels camps del formulari visibles a la pàgina','It is recommended to keep this option enabled for a better user experience.' => 'Es recomana mantenir aquesta opció activada per a una millor experiència d&#39;usuari.','Theme ZK Nito' => 'Tema ZK Nito','Add extra fields to the checkout form' => 'Afegiu camps addicionals al formulari de pagament','Adds an extra shipping email and shipping phone field to the shipping address section.' => 'Afegeix un correu electrònic d&#39;enviament addicional i un camp de telèfon d&#39;enviament a la secció d&#39;adreça d&#39;enviament.','Go to the home page' => 'Aneu a la pàgina d&#39;inici','Skip to content' => 'Saltar al contingut','Create an account' => 'Creeu un compte','Log in to your account' => 'Inicieu sessió al vostre compte','Already have an account?' => 'Ja tens un compte?','Logged in as %1$s. <a href="%2$s">Log out</a>' => 'S&#39;ha iniciat sessió com a %1$s. <a href="%2$s">Tanca la sessió</a>','Your order has a total amount due of %s. No further payment is needed.' => 'La vostra comanda té un import total pendent de %s. No cal més pagament.','Close and continue with checkout' => 'Tanqueu i continueu amb la compra','Continue' => 'Continua','Parcel terminal' => 'Terminal de paquets','<p>This widget has been replaced by Fluid Checkout. </p><p>When using Fluid Checkout, the checkout page needs to use the original WooCommerce shortcode <code>[woocommerce_checkout]</code> to work properly.</p><p>For more information, visit the Fluid Checkout documentation.</p>' => '<p>Aquest giny s&#39;ha substituït per Fluid Checkout.</p><p> Quan utilitzeu Fluid Checkout, la pàgina de pagament ha d&#39;utilitzar el codi curt original de WooCommerce <code>[woocommerce_checkout]</code> per funcionar correctament.</p><p> Per obtenir més informació, visiteu la documentació de Fluid Checkout.</p>','Theme The7' => 'Tema The7','Additional header sections' => 'Seccions de capçalera addicionals','Output additional header sections if enabled in the theme settings.' => 'Emet seccions de capçalera addicionals si està activat a la configuració del tema.','More information' => 'Més informació','Pick a Locker' => 'Tria un armari','Page template' => 'Plantilla de pàgina','Use `Order confirmation` page template for block-based themes' => 'Utilitzeu la plantilla de pàgina `Confirmació de comanda` per a temes basats en blocs','Only applies when using a block-based theme.' => 'Només s&#39;aplica quan s&#39;utilitza un tema basat en blocs.','WooCommerce Stripe Gateway' => 'Porta d&#39;enllaç de WooCommerce Stripe','Payment form' => 'Formulari de pagament','Apply styles to the Stripe payment form fields' => 'Aplicar estils als camps del formulari de pagament de Stripe','When enabled, Fluid Checkout will apply styles optimized for compatibility with the plugin. You may want to disable this if you are using custom styles for the Stripe payment form fields.' => 'Quan està activat, Fluid Checkout aplicarà estils optimitzats per a la compatibilitat amb el connector. És recomanable desactivar-ho si utilitzeu estils personalitzats per als camps del formulari de pagament de Stripe.','Theme Nyture' => 'Tema Nyture','Output the checkout steps section from the Nyture theme when using Fluid Checkout.' => 'Mostra la secció dels passos de pagament del tema Nyture quan utilitzeu Fluid Checkout.','Allows customers to make payments for orders that are either created manually by the store admin or not completed during checkout.' => 'Permet als clients fer pagaments per comandes que l&#39;administrador de la botiga ha creat manualment o que no s&#39;han completat durant el procés de compra.','The plugin WooCommerce Checkout Manager by Quadlayers is not compatible with Fluid Checkout' => 'El plugin WooCommerce Checkout Manager de Quadlayers no és compatible amb Fluid Checkout.','Company name field for billing address' => 'Camp de nom de l&#39;empresa per a l&#39;adreça de facturació','Change visibility for the company name field for the billing address section on the checkout form.' => 'Canvia la visibilitat del camp del nom de l&#39;empresa per a la secció d&#39;adreça de facturació del formulari de pagament.','Theme Bookshelf' => 'Prestatgeria temàtica','Output the checkout steps section from the Bookshelf theme when using Fluid Checkout.' => 'Mostra la secció dels passos de compra del tema Bookshelf quan utilitzeu Fluid Checkout.','Account password' => 'Contrasenya del compte','An account will be created with the information provided at checkout when completing the order.' => 'Es crearà un compte amb la informació proporcionada al moment de la compra en completar la comanda.','Choose the style of the progress bar.' => 'Trieu l&#39;estil de la barra de progrés.','Bars' => 'Bars','Theme Ireca' => 'Tema Ireca','WooCommerce page layout' => 'Disseny de pàgina de WooCommerce','Force wide layout on WooCommerce pages' => 'Forçar el disseny ample a les pàgines de WooCommerce','This ensures the content section is not too narrow on WooCommerce pages including checkout, cart, order received, order pay and account pages.' => 'Això garanteix que la secció de contingut no sigui massa estreta a les pàgines de WooCommerce, incloses les pàgines de pagament, cistella de la compra, comanda rebuda, pagament de la comanda i compte.','WooCommerce Smart Coupons' => 'Cupons intel·ligents de WooCommerce','Position on checkout page' => 'Posició a la pàgina de pagament','Choose where to display the available coupons section on the checkout page.' => 'Trieu on voleu que es mostri la secció de cupons disponibles a la pàgina de pagament.','Before the progress bar' => 'Abans de la barra de progrés','After the progress bar' => 'Després de la barra de progrés','Before coupon codes section' => 'Abans de la secció de codis de cupó','Format phone numbers according to the rules for each country.' => 'Formata els números de telèfon segons les normes de cada país.','Use precise phone number validation' => 'Utilitza una validació precisa del número de telèfon','This is an experimental feature and may not work as expected in all setups. Use it with caution.' => 'Aquesta és una funció experimental i és possible que no funcioni com s&#39;espera en totes les configuracions. Feu-la servir amb precaució.','Phone number validation types used when precise validation is enabled.' => 'Tipus de validació de números de telèfon que s&#39;utilitzen quan la validació precisa està habilitada.','Mobile' => 'Mòbil','Fixed line' => 'Línia fixa','Toll free' => 'Trucada gratuïta','Contact' => 'Contacte','Multi step' => 'Diversos passos','2 columns' => '2 columnes','1 column' => '1 columna','Before checkout steps' => 'Passos previs al pagament','Or' => 'O','When using the <em>"1 column"</em> checkout layout this option is always set to <em>"Before checkout steps"</em> and also applies to desktop view.' => 'Quan s&#39;utilitza el disseny de pagament <em>&quot;1 columna&quot;,</em> aquesta opció sempre està definida com a <em>&quot;Passos previs al pagament&quot;</em> i també s&#39;aplica a la vista d&#39;escriptori.','Position for the extra order summary section on mobile.' => 'Posició per a la secció addicional de resum de la comanda al mòbil.','The option <em>"On the site header"</em> only applies when using the distraction-free header.' => 'L&#39;opció <em>&quot;A la capçalera del lloc&quot;</em> només s&#39;aplica quan s&#39;utilitza la capçalera sense distraccions.','On the site header (requires distraction-free header)' => 'A la capçalera del lloc web (requereix una capçalera sense distraccions)','Initial state for the expansible order summary section on mobile.' => 'Estat inicial de la secció de resum de comandes expandible al mòbil.','We recommend setting it as <em>expanded</em> for the following countries due to regulatory requirements: <strong>Germany</strong>, <strong>Austria</strong>, <strong>Switzerland</strong>, <strong>Netherlands</strong>, <strong>Poland</strong>, <strong>Belgium</strong> and <strong>France</strong>.' => 'Recomanem configurar-ho com a <em>ampliat</em> per als següents països a causa dels requisits normatius: <strong>Alemanya</strong> , <strong>Àustria</strong> , <strong>Suïssa</strong> , <strong>Països Baixos</strong> , <strong>Polònia</strong> , <strong>Bèlgica</strong> i <strong>França</strong> .','Collapsed' => 'Col·lapsat','Expanded' => 'Expandit','Do not show' => 'No mostrar','yes' => 'sí','The shipping phone field may be forced as "required" if the billing address section is displayed after the shipping address section, and the billing phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'El camp del telèfon d&#39;enviament es pot forçar com a &quot;obligatori&quot; si la secció d&#39;adreça de facturació es mostra després de la secció d&#39;adreça d&#39;enviament i el camp del telèfon de facturació està definit com a &quot;obligatori&quot;. Això és necessari per garantir que l&#39;adreça d&#39;enviament es pugui copiar a l&#39;adreça de facturació quan aquesta opció estigui marcada; en cas contrari, és possible que el client no pugui completar el formulari de pagament.','The billing phone field may be forced as "required" if the billing address section is displayed before the shipping address section, and the shipping phone field is set as "required". This is needed to ensure the shipping address can be copied to the billing address when that option is checked, otherwise the customer might not be able to complete the checkout form.' => 'El camp del telèfon de facturació es pot forçar com a &quot;obligatori&quot; si la secció d&#39;adreça de facturació es mostra abans de la secció d&#39;adreça d&#39;enviament i el camp del telèfon d&#39;enviament està definit com a &quot;obligatori&quot;. Això és necessari per garantir que l&#39;adreça d&#39;enviament es pugui copiar a l&#39;adreça de facturació quan aquesta opció estigui marcada; en cas contrari, és possible que el client no pugui completar el formulari de pagament.','Settings profiles' => 'Perfils de configuració','Settings profile' => 'Perfil de configuració','You do not have permission to perform this action.' => 'No teniu permís per dur a terme aquesta acció.','You do not have permission to activate plugins.' => 'No tens permís per activar complements.','Missing plugin.' => 'Falta el complement.','Plugin activated.' => 'Complement activat.','The following changes will be applied:' => 'S&#39;aplicaran els canvis següents:','Since Fluid Checkout 5.0, settings are saved differently. Legacy options are still stored in the database to allow downgrades to previous versions if needed.' => 'Des de Fluid Checkout 5.0, la configuració es desa de manera diferent. Les opcions heretades encara s&#39;emmagatzemen a la base de dades per permetre versions anteriors si cal.','Your store has been running for about 2 weeks on the new settings so you could clean up legacy options stored in the database. Please note that after cleanup, if you need to downgrade to previous versions of the plugin it will use default values for all settings.' => 'La teva botiga ha estat funcionant durant unes 2 setmanes amb la nova configuració, de manera que pots netejar les opcions antigues emmagatzemades a la base de dades. Tingues en compte que després de la neteja, si necessites baixar a versions anteriors del connector, utilitzarà els valors predeterminats per a totes les configuracions.','Fluid Checkout settings cleanup' => 'Neteja de la configuració de Fluid Checkout','Delete leftover options' => 'Suprimeix les opcions restants','Help us improve Fluid Checkout' => 'Ajudeu-nos a millorar la caixa de fluids','Share anonymous site environment reports with Fluid Checkout to get faster support and help us improve compatibility and measure impact. No customer, user, or sensitive data are included. You can choose what is shared anytime from the Tools settings.' => 'Comparteix informes anònims de l&#39;entorn del lloc amb Fluid Checkout per obtenir una assistència més ràpida i ajudar-nos a millorar la compatibilitat i mesurar l&#39;impacte. No s&#39;hi inclouen dades de clients, usuaris ni sensibles. Pots triar què es comparteix en qualsevol moment des de la configuració d&#39;Eines.','Enable site environment reports' => 'Habilita els informes d&#39;entorn del lloc','Review settings' => 'Revisa la configuració','This preview has expired. Reload the admin page to start a new preview.' => 'Aquesta previsualització ha caducat. Torna a carregar la pàgina d&#39;administració per iniciar una nova previsualització.','Preview expired' => 'La vista prèvia ha caducat','Orders cannot be placed in the preview.' => 'No es poden fer comandes a la vista prèvia.','Logging in is not available in the preview.' => 'L&#39;inici de sessió no està disponible a la vista prèvia.','Accounts cannot be created in the preview.' => 'No es poden crear comptes a la vista prèvia.','Requests to other sites are blocked in the preview.' => 'Les sol·licituds a altres llocs estan bloquejades a la vista prèvia.','Processing…' => 'Processant…','Something went wrong. Please try again.' => 'S&#39;ha produït un error. Torna-ho a intentar.','Activate plugin' => 'Activa el complement','Fluid Checkout PRO - The complete checkout package' => 'Fluid Checkout PRO: el paquet complet de pagament','All PRO features + all add-ons, one price. Design templates, optimized cart and order received pages, account matching, and much more.' => 'Totes les funcions PRO + tots els complements, un preu. Plantilles de disseny, pàgines de cistella i comandes rebudes optimitzades, coincidència de comptes i molt més.','Optimized order pay page' => 'Pàgina de pagament de comandes optimitzada','Express checkout buttons from supported payment methods' => 'Botons de pagament exprés dels mètodes de pagament compatibles','Delayed account creation' => 'Creació de compte retardada','Address autocomplete with Google Maps APIs' => 'Autocompletar adreces amb les API de Google Maps','Multiple saved addresses with the address book' => 'Diverses adreces desades amb la llibreta d&#39;adreces','EU-VAT assistant' => 'Assistent d&#39;IVA UE','Hide this section' => 'Amaga aquesta secció','Learn more' => 'Més informació','Get early access' => 'Obtén accés anticipat','Activate add-on' => 'Activa el complement','Get more out of your checkout journey' => 'Treu més profit del teu procés de compra','Test API key' => 'Clau de prova de l&#39;API','Guided setup' => 'Configuració guiada','Options' => 'Opcions','Set up layout and design on the <a href="%s">checkout options</a>.' => 'Configura el disseny i la maquetació de les <a href="%s">opcions de pagament</a> .','Enable guest checkout and/or review <a href="%s">customer accounts settings</a>.' => 'Activa el pagament com a convidat i/o revisa <a href="%s">la configuració dels comptes dels clients</a> .','Enable optimized <a href="%1$s">cart</a>, <a href="%2$s">thank you</a> and <a href="%3$s">order pay</a> pages.' => 'Activa les pàgines optimitzades <a href="%1$s">del carretó de la compra</a> , <a href="%2$s">d&#39;agraïment</a> i <a href="%3$s">de pagament de la comanda</a> .','Enable <a href="%s">address autocomplete</a> from Google Maps.' => 'Activa <a href="%s">l&#39;autocompleció d&#39;adreces</a> des de Google Maps.','Enable multiple saved addresses with <a href="%s">address book</a>.' => 'Habilita diverses adreces desades amb <a href="%s">la llibreta d&#39;adreces</a> .','Check if there are any <a href="%s">integration options</a> available for the theme or other plugins you have installed.' => 'Comproveu si hi ha <a href="%s">opcions d&#39;integració</a> disponibles per al tema o altres complements que teniu instal·lats.','Get faster support and help us improve compatibility and measure impact. <a href="%s">Enable usage tracking</a> from the tools settings.' => 'Obtén assistència més ràpida i ajuda&#39;ns a millorar la compatibilitat i mesurar l&#39;impacte. <a href="%s">Activa el seguiment d&#39;ús</a> des de la configuració de les eines.','Missing settings tab.' => 'Falta la pestanya de configuració.','Getting started' => 'Primers passos','<strong>Great! Your checkout page is now running on Fluid Checkout.</strong> Here are a few steps to get started:' => '<strong>Fantàstic! La teva pàgina de pagament ja funciona a Fluid Checkout.</strong> Aquí tens uns quants passos per començar:','Completed' => 'Completat','Preview report data' => 'Previsualitza les dades de l&#39;informe','Send now' => 'Envia ara','Auto-detect' => 'Detecció automàtica','Afrikaans' => 'Afrikaans','Albanian' => 'Albanès','Amharic' => 'Amhàric','Arabic' => 'Àrab','Armenian' => 'Armeni','Azerbaijani' => 'Àzeri','Basque' => 'basc','Belarusian' => 'Bielorús','Bengali' => 'Bengalí','Bosnian' => 'Bosnià','Bulgarian' => 'Búlgar','Burmese' => 'Birmà','Catalan' => 'Català','Chinese' => 'xinès','Chinese (Simplified)' => 'Xinès (simplificat)','Chinese (Hong Kong)' => 'Xinès (Hong Kong)','Chinese (Traditional)' => 'Xinès (tradicional)','Croatian' => 'Croat','Czech' => 'Txec','Danish' => 'Danès','Dutch' => 'neerlandès','English' => 'Anglès','English (Australian)' => 'Anglès (australià)','English (Great Britain)' => 'Anglès (Gran Bretanya)','Estonian' => 'Estonià','Farsi' => 'Farsi','Finnish' => 'Finlandès','Filipino' => 'Filipí','French' => 'Francès','French (Canadian)' => 'Francès (canadenc)','Galician' => 'Gallec','Georgian' => 'georgià','German' => 'Alemany','Greek' => 'Grec','Gujarati' => 'Gujarati','Hebrew' => 'Hebreu','Hindi' => 'Hindi','Hungarian' => 'Hongarès','Icelandic' => 'Islandès','Indonesian' => 'Indonesi','Italian' => 'Italià','Japanese' => 'Japonès','Kannada' => 'Kannada','Kazakh' => 'Kazakh','Khmer' => 'Khmer','Korean' => 'coreà','Kyrgyz' => 'Kirguiz','Lao' => 'Laos','Latvian' => 'Letó','Lithuanian' => 'Lituà','Macedonian' => 'Macedonià','Malay' => 'Malai','Malayalam' => 'Malayalam','Marathi' => 'Marathi','Mongolian' => 'Mongol','Nepali' => 'Nepalès','Norwegian' => 'Noruec','Polish' => 'Polonès','Portuguese' => 'Portuguès','Portuguese (Brazil)' => 'Portuguès (Brasil)','Portuguese (Portugal)' => 'Portuguès (Portugal)','Punjabi' => 'Punjabi','Romanian' => 'Romanès','Russian' => 'Rus','Serbian' => 'serbi','Sinhalese' => 'Singalès','Slovak' => 'Eslovac','Slovenian' => 'Eslovè','Spanish' => 'espanyol','Spanish (Latin America)' => 'Espanyol (Amèrica Llatina)','Swahili' => 'Suahili','Swedish' => 'Suec','Tamil' => 'Tàmil','Telugu' => 'Telugu','Thai' => 'Tailandès','Turkish' => 'Turc','Ukrainian' => 'Ucraïnès','Urdu' => 'Urdú','Vietnamese' => 'Vietnamita','Zulu' => 'Zulu','Google address autocomplete' => 'Autocompletar adreces de Google','Google Places API version' => 'Versió de l&#39;API de Google Places','Choose which version of the Google Places API to use. We recommend moving to the new Places API as soon as possible.' => 'Trieu quina versió de l&#39;API de Google Places voleu utilitzar. Us recomanem que canvieu a la nova API de Places tan aviat com sigui possible.','We recommend using "Places API (New)" as effective March 1, 2025, Google will move the "Places API (Legacy)" version into Legacy status, meaning you will no longer be able to enable this service for new API keys and that that version of the API will eventually not be available anymore. Existing accounts already using the Legacy API may continue to work without disruptions.' => 'Us recomanem que utilitzeu &quot;Places API (Nova)&quot;. A partir de l&#39;1 de març de 2025, Google canviarà la versió &quot;Places API (Heredat)&quot; a Heredat, cosa que significa que ja no podreu activar aquest servei per a noves claus d&#39;API i que aquesta versió de l&#39;API deixarà d&#39;estar disponible. Els comptes existents que ja utilitzen l&#39;API Heredat poden continuar funcionant sense interrupcions.','(Recommended)' => '(Recomanat)','Google API key' => 'Clau de l&#39;API de Google','Paste your Google API key and use the test button to confirm it works for this website. Make sure the key is valid and allowed for your domain, otherwise the address field might get blocked preventing customers from completing their orders.' => 'Enganxa la teva clau API de Google i utilitza el botó de prova per confirmar que funciona per a aquest lloc web. Assegura&#39;t que la clau sigui vàlida i permesa per al teu domini; en cas contrari, el camp d&#39;adreça es podria bloquejar i impedir que els clients completin les seves comandes.','Enable Google address autocomplete' => 'Activa l&#39;autocompleció d&#39;adreces de Google','Enable address autocompletion using the Google Maps APIs.' => 'Activeu l&#39;autocompleció d&#39;adreces mitjançant les API de Google Maps.','Google API language' => 'Llenguatge de l&#39;API de Google','This language will be used to display the Google Places API address suggestions and addresses will also be autocompleted in this language.' => 'Aquest idioma s&#39;utilitzarà per mostrar els suggeriments d&#39;adreces de l&#39;API de Google Places i les adreces també s&#39;ompliran automàticament en aquest idioma.','Result types' => 'Tipus de resultats','Leave empty to accept any type of results, which usually yields better matching results. <a href="%s" target="_blank">See documentation for more details</a>. <br>Select up to 5 types of address search results to return on address autocomplete fields. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Deixeu-ho en blanc per acceptar qualsevol tipus de resultats, que normalment donen millors resultats coincidents. <a href="%s" target="_blank">Vegeu la documentació per obtenir més detalls</a> .<br> Seleccioneu fins a 5 tipus de resultats de cerca d&#39;adreces per obtenir els camps d&#39;autocompleció d&#39;adreces.<br> Visiteu la documentació de Google Maps per obtenir més informació sobre els <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">tipus compatibles</a> .','Result types (Legacy API)' => 'Tipus de resultats (API antiga)','Which type of address search results to return when using Places API (Legacy). <br>Visit the documentation of the Legacy Google Places API to learn more about the <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">supported types</a>.' => 'Quin tipus de resultats de cerca d&#39;adreces retornar quan s&#39;utilitza l&#39;API de Places (Legacy).<br> Visiteu la documentació de l&#39;API de Google Places antiga per obtenir més informació sobre els <a href="https://developers.google.com/maps/documentation/places/web-service/supported_types#table3" target="_blank">tipus compatibles</a> .','Company fields' => 'Camps de l&#39;empresa','Enable autocomplete for the company name if available' => 'Habilita l&#39;autocompleció per al nom de l&#39;empresa si està disponible','Enable autocompletion of the company field with the company name information when returned from the Google Maps APIs.' => 'Activa l&#39;autocompleció del camp de l&#39;empresa amb la informació del nom de l&#39;empresa quan es retorna des de les API de Google Maps.','Business search' => 'Cerca d&#39;empreses','Enable search for businesses in the company field' => 'Habilita la cerca d&#39;empreses al camp de l&#39;empresa','Enable suggestion of addresses associated with a business when typing in the company field, then autocomplete all addresses fields when a business is selected from the suggestions.' => 'Activa el suggeriment d&#39;adreces associades a una empresa quan s&#39;escriu al camp de l&#39;empresa i, a continuació, completa automàticament tots els camps d&#39;adreces quan se seleccioni una empresa dels suggeriments.','Company result types' => 'Tipus de resultats de l&#39;empresa','Select up to 5 types of address search results to return on autocomplete company fields. <br>Recommended value is <code>establishment</code>, which includes most types of businesses. <br>Leave empty to accept any type of results, including results that are not related to businesses. <br>Visit the Google Maps documentation to learn more about the <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">supported types</a>.' => 'Seleccioneu fins a 5 tipus de resultats de cerca d&#39;adreces per retornar-los als camps d&#39;empresa d&#39;autocompleció.<br> El valor recomanat és <code>establishment</code> , que inclou la majoria de tipus d&#39;empreses.<br> Deixeu-ho en blanc per acceptar qualsevol tipus de resultats, inclosos els resultats que no estiguin relacionats amb empreses.<br> Visiteu la documentació de Google Maps per obtenir més informació sobre els <a href="https://developers.google.com/maps/documentation/javascript/place-types" target="_blank">tipus compatibles</a> .','Google logo' => 'Logotip de Google','Show text and logo "Powered by Google"' => 'Mostra el text i el logotip &quot;Amb tecnologia de Google&quot;','When checked, the text and logo "Powered by Google" will be displayed at the bottom of the address autocomplete suggestions box.' => 'Quan estigui marcat, el text i el logotip &quot;Powered by Google&quot; es mostraran a la part inferior del quadre de suggeriments d&#39;autocompleció d&#39;adreces.','Brasil API address autocomplete' => 'Autocompletar adreça API Brasil','Brasil API' => 'API del Brasil','Enable Brasil API address autocomplete for CEP fields' => 'Activa l&#39;autocompleció d&#39;adreces de l&#39;API del Brasil per als camps del CEP','Use Brasil API to retrieve and autofill addresses using the CEP/Postcode field. Only relevant for Brazilian addresses.' => 'Feu servir l&#39;API del Brasil per recuperar i emplenar automàticament les adreces mitjançant el camp CEP/Codi postal. Només és rellevant per a les adreces brasileres.','API version' => 'Versió de l&#39;API','Choose which version of the Brasil API CEP method to use.' => 'Trieu quina versió del mètode CEP de l&#39;API de Brasil voleu utilitzar.','Address book migration' => 'Migració de la llibreta d&#39;adreces','WooCommerce addresses' => 'Adreces de WooCommerce','Copy existing shipping and billing addresses from WooCommerce into the customers\' address book.' => 'Copieu les adreces d&#39;enviament i facturació existents de WooCommerce a la llibreta d&#39;adreces dels clients.','Enable the address book feature' => 'Activa la funció de llibreta d&#39;adreces','Allow customers to save multiple addresses and define the default address to be used for shipping and billing.' => 'Permet als clients desar diverses adreces i definir l&#39;adreça predeterminada que s&#39;utilitzarà per a l&#39;enviament i la facturació.','Address labels' => 'Etiquetes d&#39;adreça','Allow customers to add a custom label for each address' => 'Permetre que els clients afegeixin una etiqueta personalitzada per a cada adreça','Address labels make it easier to for customers to distinguish between their saved addresses (ie.: "Mom\'s House"). The address labels are private to the customers, and will not be displayed or printed on the order details page or invoices.' => 'Les etiquetes d&#39;adreça faciliten que els clients distingeixin entre les seves adreces desades (per exemple: &quot;Casa de la mare&quot;). Les etiquetes d&#39;adreça són privades per als clients i no es mostraran ni s&#39;imprimiran a la pàgina de detalls de la comanda ni a les factures.','Display layout' => 'Disseny de la pantalla','Choose how saved addresses are displayed at checkout and on the cart.' => 'Trieu com es mostren les adreces desades al finalitzar la compra i al carretó de la compra.','Applies at checkout and on the cart. Saved addresses on the account page always use the cards layout.' => 'S&#39;aplica al moment de pagar i al carretó de la compra. Les adreces desades a la pàgina del compte sempre utilitzen el disseny de les targetes.','Address cards' => 'Targetes d&#39;adreça','Address list' => 'Llista d&#39;adreces','Dropdown field' => 'Camp desplegable','Address search' => 'Cerca d&#39;adreces','Show address search filter on frontend when customer has at least this number of saved addresses available.' => 'Mostra el filtre de cerca d&#39;adreces al front-end quan el client tingui com a mínim aquest nombre d&#39;adreces desades disponibles.','Not used when display layout is set to dropdown field.' => 'No s&#39;utilitza quan el disseny de visualització està definit com a camp desplegable.','Addresses' => 'Adreces','Enable cart page optimizations to see more options' => 'Activa les optimitzacions de la pàgina del carretó per veure més opcions','Sticky order summary' => 'Resum de l&#39;ordre fixa','Select position where to display the coupon codes section on the cart page. Only applicable when AJAX cart is enabled, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Seleccioneu la posició on voleu que es mostri la secció de codis de cupó a la pàgina del carretó. Només s&#39;aplica quan el carretó AJAX està habilitat i si l&#39;ús de codis de cupó està habilitat a la configuració de WooCommerce.','Layout of cross-sell' => 'Disseny de la venda creuada','Cross-sells displayed' => 'Vendes creuades mostrades','Items' => 'Articles','Cart page optimization' => 'Optimització de la pàgina del carretó','Give your cart the same clear, conversion-focused layout as your checkout.' => 'Doneu al carretó de la compra el mateix disseny clar i centrat en la conversió que al pagament.','Match the cart layout to the checkout page for a consistent purchase journey.' => 'Fes coincidir el disseny del carretó de la compra amb la pàgina de pagament per a un procés de compra coherent.','Keep the cart always updated in the background, no full page reloads when quantities change.' => 'Mantingueu el carretó sempre actualitzat en segon pla, sense recàrregues de pàgina completa quan canvien les quantitats.','Place coupon codes, shipping, and cross-sells exactly where they convert best.' => 'Col·loca codis de cupó, enviament i vendes creuades exactament on converteixin millor.','Keep the order summary visible while scrolling, and add trust symbols where shoppers need reassurance.' => 'Mantingueu el resum de la comanda visible mentre us desplaceu i afegiu símbols de confiança on els compradors necessitin tranquil·litat.','Columns' => 'Columnes','General styles for the checkout steps, order summary and other sections. Applies to other checkout, cart, thank you (order received), and view order pages.' => 'Estils generals per als passos de pagament, el resum de la comanda i altres seccions. S&#39;aplica a altres pàgines de pagament, cistella, agraïment (comanda rebuda) i visualització de la comanda.','When using the <em>"1 column"</em> layout with the <em>"Split"</em> design template, a right column is shown only if the page sidebar widget area is active (Checkout Sidebar, Cart Sidebar, or Order Received Sidebar). Otherwise the page stays as a single column with Split styles.' => 'Quan s&#39;utilitza el disseny <em>&quot;1 columna&quot;</em> amb la plantilla de disseny <em>&quot;Dividit&quot;</em> , només es mostra una columna dreta si l&#39;àrea del widget de la barra lateral de la pàgina està activa (barra lateral de pagament, barra lateral del carretó o barra lateral de comanda rebuda). En cas contrari, la pàgina es manté com una sola columna amb estils dividits.','Split column background' => 'Fons de columna dividit','Choose a background color for the Split design secondary column. Leave empty to use the order summary background color.' => 'Trieu un color de fons per a la columna secundària Disseny dividit. Deixeu-ho en blanc per utilitzar el color de fons del resum de la comanda.','Page templates' => 'Plantilles de pàgina','Checkout template' => 'Plantilla de pagament','Recommended for fewer distractions at checkout. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Read the research about cart abandonment</a>.' => 'Recomanat per tenir menys distraccions a l&#39;hora de pagar. <a href="https://baymard.com/blog/cart-abandonment" target="_blank">Llegiu la recerca sobre l&#39;abandonament del carretó</a> de la compra.','Sticky progress bar' => 'Barra de progrés fixa','Progress bar style' => 'Estil de barra de progrés','Order totals' => 'Totals de la comanda','Background color' => 'Color de fons','Action link' => 'Enllaç d&#39;acció','Mobile order summary' => 'Resum de la comanda per a mòbils','Mobile initial state' => 'Estat inicial del mòbil','Enable editing cart items at checkout' => 'Activa l&#39;edició dels articles del carretó al finalitzar la compra','Allow customers to change product quantities or remove items directly at the checkout page.' => 'Permet als clients canviar les quantitats de productes o eliminar articles directament a la pàgina de pagament.','Cart item errors' => 'Errors dels articles del carretó','Only applicable when coupon code is displayed as a separate section on the checkout or cart pages, and if use of coupon codes are enabled in the WooCommerce settings.' => 'Només s&#39;aplica quan el codi de cupó es mostra com una secció separada a les pàgines de pagament o de la cistella de la compra, i si l&#39;ús de codis de cupó està habilitat a la configuració de WooCommerce.','Coupon codes position' => 'Posició dels codis de cupó','Apply coupon button' => 'Botó Aplica cupó','Select style of the "apply coupon" button.' => 'Seleccioneu l&#39;estil del botó &quot;aplica el cupó&quot;.','Address line 2' => 'Línia d&#39;adreça 2','This setting is shared between the Checkout and Local pickup sections. On the Local pickup section, it also decides whether the Ship/Pickup selector shows inside the shipping method section (before the address) or as a separate section (after).' => 'Aquesta configuració es comparteix entre les seccions Finalitzar compra i Recollida local. A la secció Recollida local, també decideix si el selector Enviament/Recollida es mostra dins de la secció del mètode d&#39;enviament (abans de l&#39;adreça) o com a secció separada (després).','Customer accounts' => 'Comptes de clients','Guest checkout' => 'Sortida de client','Guest checkout, login, and account creation options from the WooCommerce Accounts settings page. They are managed here for your convenience, and so you can use different values per settings profile.' => 'Opcions de pagament, inici de sessió i creació de comptes com a convidat des de la pàgina de configuració de comptes de WooCommerce. Es gestionen aquí per a la vostra comoditat i, per tant, podeu utilitzar valors diferents per a cada perfil de configuració.','Allow customers to checkout without an account' => 'Permetre que els clients finalitzin la compra sense un compte','<strong>Recommended</strong> so customers are not asked to create an account or log in during checkout, which can lower conversion rates.' => '<strong>Recomanat</strong> perquè no se&#39;ls demani als clients que creïn un compte o iniciïn sessió durant el pagament, cosa que pot reduir les taxes de conversió.','When disabled, customers must log in or create an account to complete the purchase.' => 'Quan està desactivat, els clients han d&#39;iniciar sessió o crear un compte per completar la compra.','Login at checkout' => 'Inicia la sessió al finalitzar la compra','Enable log-in during checkout' => 'Habilita l&#39;inici de sessió durant el pagament','Show a link for returning customers to log in from the checkout page.' => 'Mostra un enllaç perquè els clients recurrents puguin iniciar la sessió des de la pàgina de pagament.','Account creation' => 'Creació de compte','Allow customers to create an account during checkout' => 'Permetre que els clients creïn un compte durant el pagament','Customers can create an account before placing their order.' => 'Els clients poden crear un compte abans de fer la seva comanda.','Allow customers to create an account from the My account page' => 'Permetre que els clients creïn un compte des de la pàgina El meu compte','Customers can register a new account from the My account page.' => 'Els clients poden registrar un compte nou des de la pàgina El meu compte.','Username' => 'Nom d&#39;usuari','Generate from customer\'s name' => 'Generar a partir del nom del client','<strong>Recommended</strong> so customers are not asked to choose a username during checkout, which can lower conversion rates.' => '<strong>Recomanat</strong> perquè no se&#39;ls demani als clients que triïn un nom d&#39;usuari durant el procés de compra, cosa que pot reduir les taxes de conversió.','A username is generated from the customer name, or from the email address when a name cannot be used.' => 'Es genera un nom d&#39;usuari a partir del nom del client o, si no es pot utilitzar un nom, a partir de l&#39;adreça de correu electrònic.','Password' => 'Contrasenya','Send password setup link' => 'Enviar enllaç de configuració de contrasenya','<strong>Recommended</strong> so customers are not asked to set a password during checkout, which can lower conversion rates.' => '<strong>Recomanat</strong> perquè no se&#39;ls demani als clients que estableixin una contrasenya durant el procés de compra, cosa que pot reduir les taxes de conversió.','Customers receive an email to create their password securely.' => 'Els clients reben un correu electrònic per crear la seva contrasenya de manera segura.','Let registered customers complete checkout without logging in and associate the order with their existing account when contact details match.' => 'Permet que els clients registrats completin la compra sense iniciar sessió i associïn la comanda amb el seu compte existent quan les dades de contacte coincideixin.','Existing account message' => 'Missatge del compte existent','Let customers create an account after placing their order, from the thank you page.' => 'Permet que els clients creïn un compte després de fer la comanda, des de la pàgina d&#39;agraïment.','Options in this section are available when guest checkout and account matching are enabled. Enable both features above to configure delayed account creation.' => 'Les opcions d&#39;aquesta secció estan disponibles quan el pagament com a convidat i la coincidència de comptes estan habilitades. Activeu les dues funcions anteriors per configurar la creació diferida del compte.','Enable delayed account creation' => 'Activa la creació de comptes retardada','Enable delayed account creation when both guest checkout and account matching are enabled.' => 'Activa la creació de comptes diferida quan tant la compra com la coincidència de comptes estan habilitades.','Section position' => 'Posició de la secció','Before customer details section' => 'Abans de la secció de detalls del client','After customer details section' => 'Després de la secció de detalls del client','Account creation benefits' => 'Beneficis de la creació de comptes','Leaving the field empty will display the default text.' => 'Si deixeu el camp buit, es mostrarà el text per defecte.','Inline buttons' => 'Botons en línia','Required fields' => 'Camps obligatoris','Enable gift message fields at checkout' => 'Activa els camps de missatge de regal al finalitzar la compra','Expanded gift message' => 'Missatge de regal ampliat','Display gift message field always expanded' => 'Camp de missatge de regal que es mostra sempre expandit','Gift message in order details' => 'Missatge de regal als detalls de la comanda','No integrations available at the moment on this section. The options related to each plugin and theme will only appear here when that plugin or theme is activated.' => 'No hi ha integracions disponibles en aquest moment en aquesta secció. Les opcions relacionades amb cada complement i tema només apareixeran aquí quan aquest complement o tema estigui activat.','Phone fields' => 'Camps de telèfon','Field visibility' => 'Visibilitat al camp','Field position' => 'Posició de camp','Phone country code & validation' => 'Codi telefònic de país i validació','Country' => 'País','Enable country on phone fields' => 'Habilita el país als camps de telèfon','Filter countries for shipping or billing' => 'Filtrar països per a enviament o facturació','Limit the country selector on each phone field to the countries allowed for shipping or billing on your store.' => 'Limita el selector de país a cada camp de telèfon als països permesos per a l&#39;enviament o la facturació a la teva botiga.','Validation' => 'Validació','Enable simple validation based on country rules' => 'Habilita la validació simple basada en les normes del país','Checks that the phone number is valid for the selected country, including country code and length.' => 'Comprova que el número de telèfon sigui vàlid per al país seleccionat, incloent-hi el codi de país i la longitud.','Stricter check that the number is a valid mobile, fixed line, or other accepted type for the selected country. May reject some valid numbers.' => 'Comprovació més estricta que el número sigui un mòbil, una línia fixa o un altre tipus acceptat vàlid per al país seleccionat. És possible que alguns números vàlids siguin rebutjats.','Validation types' => 'Tipus de validació','Placeholders' => 'Marcadors de posició','No license keys to manage at the moment. License keys will appear here when a licensed Fluid Checkout plugin or add-on is active.' => 'No hi ha claus de llicència per gestionar en aquest moment. Les claus de llicència apareixeran aquí quan un complement o complement de Fluid Checkout amb llicència estigui actiu.','Default delivery type' => 'Tipus de lliurament predeterminat','Choose which delivery type will be selected by default.' => 'Trieu quin tipus de lliurament es seleccionarà per defecte.','Shipping zone fields' => 'Camps de zona d&#39;enviament','Choose which fields will be displayed for the local pickup shipping zone filter fields. Leave empty to show all available options.' => 'Trieu quins camps es mostraran per als camps del filtre de la zona d&#39;enviament de recollida local. Deixeu-ho en blanc per mostrar totes les opcions disponibles.','These fields will be displayed as a filter for the local pickup shipping methods. Some fields might still appear at checkout when not selected here, if compatible plugins require them to work properly.' => 'Aquests camps es mostraran com a filtre per als mètodes d&#39;enviament de recollida local. Alguns camps encara poden aparèixer al moment de la compra si no estan seleccionats aquí, si els complements compatibles requereixen que funcionin correctament.','Order shipping address' => 'Adreça d&#39;enviament de la comanda','Order pay page optimization' => 'Optimització de la pàgina de pagament de comandes','Give unpaid orders the same clear, conversion-focused layout as checkout.' => 'Doneu a les comandes impagades el mateix disseny clar i centrat en la conversió que al pagament.','Optimize the layout of the order pay page for orders pending payment.' => 'Optimitza el disseny de la pàgina de pagament de comandes per a les comandes pendents de pagament.','Match the order pay experience to your checkout for a consistent purchase journey.' => 'Fes coincidir l&#39;experiència de pagament de la comanda amb el procés de compra per a un procés de compra coherent.','Add trust symbols and badges where shoppers need reassurance before paying.' => 'Afegiu símbols i distintius de confiança on els compradors necessitin tranquil·litat abans de pagar.','Thank you page optimization' => 'Optimització de la pàgina d&#39;agraïment','Make the thank you page and order details clearer for customers after they buy.' => 'Feu que la pàgina d&#39;agraïment i els detalls de la comanda siguin més clars per als clients després de la compra.','Optimize the thank you page and account order details with a clearer layout.' => 'Optimitza la pàgina d&#39;agraïment i els detalls de la comanda del compte amb un disseny més clar.','Show order status progress, actions, downloads, and notes where they make sense.' => 'Mostra el progrés de l&#39;estat de la comanda, les accions, les descàrregues i les notes on tinguin sentit.','Customize order details sections on email notifications.' => 'Personalitza les seccions de detalls de la comanda a les notificacions per correu electrònic.','Add trust symbols and badges where shoppers need reassurance after purchase.' => 'Afegiu símbols i distintius de confiança on els compradors necessitin tranquil·litat després de la compra.','Email notifications' => 'Notificacions per correu electrònic','Enable thank you page and order details optimizations to see more options' => 'Activa les optimitzacions de la pàgina d&#39;agraïment i dels detalls de la comanda per veure més opcions','Use wide layout on thank you page' => 'Utilitza un disseny ample a la pàgina d&#39;agraïment','These options affect the thank you page, view order details on account pages and on email notifications.' => 'Aquestes opcions afecten la pàgina d&#39;agraïment, la visualització dels detalls de la comanda a les pàgines del compte i les notificacions per correu electrònic.','Save settings' => 'Desa la configuració','Docs' => 'Documents','Cart' => 'Carro','Thank you' => 'Gràcies','Address autocomplete' => 'Autocompletar l&#39;adreça','Trust badges' => 'Insígnies de confiança','You do not have permission to save these settings.' => 'No teniu permís per desar aquesta configuració.','Invalid save request.' => 'Sol·licitud de desament no vàlida.','Your settings have been saved.' => 'La configuració s&#39;ha desat.','Saving...' => 'Desant...','Settings could not be saved. Please try again.' => 'No s&#39;ha pogut desar la configuració. Torna-ho a provar.','Dismiss notice' => 'Desestima l&#39;avís','Open settings menu' => 'Obre el menú de configuració','Close settings menu' => 'Tanca el menú de configuració','Preview' => 'Vista prèvia','Expand preview' => 'Expandeix la vista prèvia','Collapse preview' => 'Replega la vista prèvia','Show header and footer' => 'Mostra la capçalera i el peu de pàgina','Hide header and footer' => 'Amaga la capçalera i el peu de pàgina','Page preview' => 'Vista prèvia de la pàgina','Preview viewport' => 'Vista prèvia','Tablet' => 'Tauleta','Desktop' => 'Escriptori','Preview width' => 'Amplada de la previsualització','Decrease width' => 'Reduir l&#39;amplada','Preview width in pixels' => 'Amplada de la previsualització en píxels','Increase width' => 'Augmenta l&#39;amplada','Preview as' => 'Previsualitza com a','Guest' => 'Convidat','Logged in' => 'Sessió iniciada','Preview page' => 'Pàgina de previsualització','Expand preview for a closer look' => 'Amplia la vista prèvia per veure-ho de més a prop','Available with %s.' => 'Disponible amb %s.','Turn them on' => 'Activa&#39;ls','Optimizations for this page are turned off. %s to preview the page.' => 'Les optimitzacions per a aquesta pàgina estan desactivades. %s per previsualitzar la pàgina.','%s preview' => 'Vista prèvia de %s','Isolated session · nothing is saved' => 'Sessió aïllada · no es desa res','Usage tracking' => 'Seguiment d&#39;ús','Send non-sensitive site environment reports to help Fluid Checkout improve compatibility. Reports are not sent until enabled in the options below.' => 'Envia informes no confidencials de l&#39;entorn del lloc per ajudar Fluid Checkout a millorar la compatibilitat. Els informes no s&#39;envien fins que no s&#39;hagin activat a les opcions següents.','Send usage tracking reports to Fluid Checkout' => 'Enviar informes de seguiment d&#39;ús a Fluid Checkout','These reports help us improve compatibility and support for your site and are sent weekly when enabled.' => 'Aquests informes ens ajuden a millorar la compatibilitat i el suport per al vostre lloc web i s&#39;envien setmanalment quan estan activats.','No customer, admin user, or any other sensitive data is included in the reports.' => 'No s&#39;inclouen dades de clients, usuaris administradors ni altres dades sensibles als informes.','Basic environment info' => 'Informació bàsica sobre l&#39;entorn','WordPress, PHP, WooCommerce, theme, and plugin list data. Always included when reporting is enabled. Helps us understand the environment your site is running in.' => 'Dades de WordPress, PHP, WooCommerce, temes i llista de complements. Sempre s&#39;inclouen quan els informes estan activats. Ens ajuden a entendre l&#39;entorn en què s&#39;executa el vostre lloc web.','Plugin settings' => 'Configuració del complement','Sends Fluid Checkout plugin settings to help with support requests and helps us understand how you are using our plugins.' => 'Envia la configuració del complement Fluid Checkout per ajudar amb les sol·licituds d&#39;assistència i ens ajuda a entendre com utilitzeu els nostres complements.','Coming soon' => 'Properament','Sales metrics' => 'Mètriques de vendes','Monthly order count and total sales for one year prior to installing Fluid Checkout up to today. Helps us understand if you are making more money with our plugins installed. No customer or user data is ever sent.' => 'Recompte mensual de comandes i vendes totals d&#39;un any abans d&#39;instal·lar Fluid Checkout fins avui. Ens ajuda a entendre si guanyes més diners amb els nostres complements instal·lats. No s&#39;envien mai dades de clients ni d&#39;usuaris.','Utilities' => 'Serveis públics','Use <code>TomSelect</code> dropdown components instead of <code>select2</code>' => 'Utilitza els components desplegables <code>TomSelect</code> en comptes de <code>select2</code>','TomSelect is a simpler dropdown selection component which is less prone to errors than Select2, while offering the same functionality.' => 'TomSelect és un component de selecció desplegable més senzill que és menys propens a errors que Select2, tot i que ofereix la mateixa funcionalitat.','Sets the font size inside form fields to 16px on pages optimized by this plugin to avoid automatically zooming in when interacting with form fields on small devices.' => 'Estableix la mida de la lletra dins dels camps del formulari a 16 px a les pàgines optimitzades per aquest connector per evitar que s&#39;ampliï automàticament la imatge en interactuar amb els camps del formulari en dispositius petits.','Safari and other browsers might automatically zoom in on mobile devices to make the text easier to read when the font size is smaller than 16px.' => 'El Safari i altres navegadors poden fer zoom automàticament en dispositius mòbils per facilitar la lectura del text quan la mida de la lletra és inferior a 16 px.','Enable script processing tracking on the browser console.' => 'Activa el seguiment del processament de scripts a la consola del navegador.','Unminified assets' => 'Actius no minimitzats','Google Maps scripts' => 'Scripts de Google Maps','Do not remove duplicate Google Maps scripts' => 'No suprimiu els scripts duplicats de Google Maps','When enabled, duplicate Google Maps scripts will NOT be removed which can cause errors and performance issues. Only use this option while troubleshooting.' => 'Quan està activat, els scripts duplicats de Google Maps NO s&#39;eliminaran, cosa que pot causar errors i problemes de rendiment. Només feu servir aquesta opció durant la resolució de problemes.','Widget areas' => 'Àrees de widgets','Last step on mobile' => 'Últim pas al mòbil','Display widgets only at last step on mobile' => 'Mostra els widgets només a l&#39;últim pas al mòbil','Display checkout trust badge widgets only when viewing the last checkout step on mobile devices' => 'Mostra els widgets de la insígnia de confiança del pagament només quan es visualitza l&#39;últim pas del pagament en dispositius mòbils','Standard' => 'Estàndard','VAT number field' => 'Camp del número d&#39;IVA','Add a VAT number field to the billing form.' => 'Afegiu un camp de número d&#39;IVA al formulari de facturació.','Field label' => 'Etiqueta del camp','Set the label of the VAT number field (ie. VAT number). On multi-language websites, it is better to leave this field empty and translate the original string.' => 'Estableix l&#39;etiqueta del camp del número d&#39;IVA (és a dir, número d&#39;IVA). En llocs web multilingües, és millor deixar aquest camp buit i traduir la cadena original.','VAT Number' => 'Número d&#39;IVA','EU-VAT' => 'IVA UE','Enable the VAT number field to see more options' => 'Activa el camp del número d&#39;IVA per veure més opcions','VAT validation' => 'Validació de l&#39;IVA','Validate VAT number field for EU-VAT during checkout' => 'Valida el camp del número d&#39;IVA per a l&#39;IVA de la UE durant el pagament','Checks if the VAT Number provided is a valid VAT number registered on the European VIES Database (VAT Information Exchange System).' => 'Comprova si el número d&#39;IVA proporcionat és un número d&#39;IVA vàlid registrat a la base de dades VIES europea (Sistema d&#39;intercanvi d&#39;informació sobre l&#39;IVA).','Shop VAT number' => 'Número d&#39;IVA de la botiga','The shop\'s VAT number used for requesting EU-VAT validation, and printed on invoices. <br><strong>We strongly recommend adding your Shop VAT number</strong> as otherwise the VIES consultation results might not be valid for accounting purposes. <br>Ie.: <code>ATU99999999</code> or <code>EE999999999</code>.' => 'El número d&#39;IVA de la botiga utilitzat per sol·licitar la validació de l&#39;IVA de la UE i imprès a les factures.<br> <strong>Us recomanem fermament que afegiu el número d&#39;IVA de la vostra botiga,</strong> ja que en cas contrari els resultats de la consulta VIES podrien no ser vàlids a efectes comptables.<br> És a dir: <code>ATU99999999</code> o <code>EE999999999</code> .','Reverse charge' => 'Cobrament invers','Apply reverse charge mechanism' => 'Aplicar el mecanisme de càrrec invers','Set tax rate to zero and display "Reverse charge" on invoices when the customer\'s VAT number is valid. A different "Reverse charge" text might be required depending on the store\'s country.' => 'Estableix el tipus impositiu a zero i mostra &quot;Cargament invers&quot; a les factures quan el número d&#39;IVA del client sigui vàlid. Pot ser que es requereixi un text de &quot;Cargament invers&quot; diferent segons el país de la botiga.','Same country' => 'El mateix país','Apply reverse charge mechanism for transactions in the shop country:' => 'Aplica el mecanisme de cobro invers per a les transaccions al país de la botiga:','Enables applying reverse charge mechanism for transactions between companies in the same country as the shop.' => 'Permet aplicar el mecanisme de càrrec invers per a transaccions entre empreses del mateix país que la botiga.','Reverse charge exceptions' => 'Excepcions de càrrec invers','Select additional countries to skip applying the reverse charge mechanism.' => 'Seleccioneu altres països per ometre l&#39;aplicació del mecanisme de cobrament invers.','Taxes will be charged to orders from these countries even when a valid VAT number is provided.' => 'Es cobraran impostos a les comandes d&#39;aquests països fins i tot quan es proporcioni un número d&#39;IVA vàlid.','Reverse charge label on invoices' => 'Etiqueta de cobro invers a les factures','Set the label of "reverse charge" on the checkout page and order details.' => 'Estableix l&#39;etiqueta de &quot;cobrament invers&quot; a la pàgina de pagament i als detalls de la comanda.','Reverse charge text on invoices' => 'Text de cobro invers a les factures','Set the label of "reverse charge" text on invoices.' => 'Estableix l&#39;etiqueta de text &quot;reversió de càrrec&quot; a les factures.','Tax to be paid on reverse charge basis' => 'Impost a pagar amb càrrec invers','Company name' => 'Nom de l&#39;empresa','Autocomplete company name from VAT number' => 'Autocompletar el nom de l&#39;empresa a partir del número d&#39;IVA','Fill in the billing company name based on the valid VAT number provided by the customer.' => 'Empleneu el nom de l&#39;empresa de facturació segons el número d&#39;IVA vàlid proporcionat pel client.','Company name editing' => 'Edició del nom de l&#39;empresa','Allow editing of auto-filled company name' => 'Permet l&#39;edició del nom de l&#39;empresa omplert automàticament','When enabled, customers can change the company name associated with the provided VAT number.' => 'Quan està activat, els clients poden canviar el nom de l&#39;empresa associat amb el número d&#39;IVA proporcionat.','EU-VAT for digital goods' => 'IVA de la UE per a béns digitals','From January 1st, 2015, modifications have been made to the EU VAT regulations concerning digital goods, impacting exclusively B2C transactions. The VAT on digital goods must be calculated based on the customer\'s location, and evidence of this needs to be collected (IP address and billing address).' => 'A partir de l&#39;1 de gener de 2015, s&#39;han introduït modificacions a la normativa de l&#39;IVA de la UE relativa als béns digitals, que afecten exclusivament les transaccions B2C. L&#39;IVA dels béns digitals s&#39;ha de calcular en funció de la ubicació del client i cal recopilar proves d&#39;això (adreça IP i adreça de facturació).','Tax classes for digital goods' => 'Classes impositives per a béns digitals','Select some tax classes' => 'Seleccioneu algunes classes d&#39;impostos','Location evidence' => 'Evidència de localització','Collect customer\'s location evidence' => 'Recopilar proves de la ubicació del client','Saves the IP address and validate it against the customer\'s billing address. Customer\'s must confirm their billing address by checking a checkbox on the checkout page if the country from their billing address and IP do not match.' => 'Desa l&#39;adreça IP i la valida amb l&#39;adreça de facturació del client. Els clients han de confirmar la seva adreça de facturació marcant una casella de selecció a la pàgina de pagament si el país de la seva adreça de facturació i la IP no coincideixen.','This option is managed in Fluid Checkout. <a href="%s">Change it in Customer accounts settings</a>.' => 'Aquesta opció es gestiona a Fluid Checkout. <a href="%s">Canvieu-la a la configuració dels comptes de client</a> .','This option is managed in Fluid Checkout. Change it under Fluid Checkout > Customer accounts.' => 'Aquesta opció es gestiona a Fluid Checkout. Canvieu-la a Fluid Checkout &gt; Comptes de client.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available in the <a href="%s">Fluid Checkout settings</a>.' => 'Aquesta opció es gestiona a Fluid Checkout. La destinació d&#39;enviament sempre està definida com a &quot;Adreça d&#39;enviament del client per defecte&quot; quan Fluid Checkout està activat. Els clients encara poden proporcionar adreces d&#39;enviament i facturació diferents durant el pagament.<br><br> A la <a href="%s">configuració de Fluid Checkout</a> hi ha una opció per definir l&#39;adreça de facturació predeterminada perquè sigui la mateixa que l&#39;adreça d&#39;enviament.','This option is managed in Fluid Checkout. The shipping destination is always set to "Default to customer shipping address" when Fluid Checkout is activated. Customers can still provide different shipping and billing addresses during checkout.<br><br>An option for setting the default billing address to be the same as the shipping address is available at WooCommerce > Settings > Fluid Checkout.' => 'Aquesta opció es gestiona a Fluid Checkout. La destinació d&#39;enviament sempre està definida com a &quot;Adreça d&#39;enviament del client per defecte&quot; quan Fluid Checkout està activat. Els clients encara poden proporcionar adreces d&#39;enviament i facturació diferents durant el pagament.<br><br> Una opció per definir l&#39;adreça de facturació predeterminada perquè sigui la mateixa que l&#39;adreça d&#39;enviament està disponible a WooCommerce &gt; Configuració &gt; Fluid Checkout.','These settings have been moved to WP Admin > Fluid Checkout > Settings.' => 'Aquests paràmetres s&#39;han mogut a WP Admin &gt; Fluid Checkout &gt; Configuració.','This WooCommerce Settings tab is deprecated and will be removed in Fluid Checkout 6.0.' => 'Aquesta pestanya Configuració de WooCommerce està obsoleta i s&#39;eliminarà a Fluid Checkout 6.0.','Go to settings page' => 'Ves a la pàgina de configuració','Hide this tab permanently' => 'Amaga aquesta pestanya permanentment','Site report preview' => 'Vista prèvia de l&#39;informe del lloc','This is the data that would be included in the next site environment report based on your current settings.' => 'Aquestes són les dades que s&#39;inclourien al següent informe de l&#39;entorn del lloc segons la vostra configuració actual.','Loading report preview...' => 'S&#39;està carregant la vista prèvia de l&#39;informe...','Could not load the site report preview. Try again.' => 'No s&#39;ha pogut carregar la vista prèvia de l&#39;informe del lloc. Torna-ho a provar.','Could not send the site report. Try again.' => 'No s&#39;ha pogut enviar l&#39;informe del lloc. Torna-ho a provar.','Site report sent successfully.' => 'L&#39;informe del lloc s&#39;ha enviat correctament.','Enable and send now' => 'Activa i envia ara','Close' => 'Tanca','A site report request is already in progress. Try again in a moment.' => 'Ja hi ha una sol·licitud d&#39;informe del lloc en curs. Torna-ho a provar d&#39;aquí a un moment.','Site environment reporting is disabled.' => 'Els informes d&#39;entorn del lloc estan desactivats.','No site report data is available to send.' => 'No hi ha dades d&#39;informe del lloc disponibles per enviar.','This site domain cannot send environment reports (local or development domains are excluded).' => 'Aquest domini de lloc no pot enviar informes d&#39;entorn (els dominis locals o de desenvolupament estan exclosos).','A site report was sent recently. Try again later.' => 'Recentment s&#39;ha enviat un informe del lloc. Torna-ho a provar més tard.','The site report could not be sent. Try again later.' => 'No s&#39;ha pogut enviar l&#39;informe del lloc. Torna-ho a provar més tard.','Site environment reporting is not available.' => 'Els informes de l&#39;entorn del lloc no estan disponibles.','No site report data is available for the selected settings.' => 'No hi ha dades d&#39;informe del lloc disponibles per a la configuració seleccionada.','You are not allowed to manage site reports.' => 'No tens permís per gestionar informes del lloc.','PRO feature' => 'Funció PRO','Other plugins' => 'Altres complements','Get only this add-on &mdash; %s' => 'Obtén només aquest complement — %s','Install add-on' => 'Instal·la el complement','Upgrade to PRO &mdash; %s' => 'Actualitza a PRO — %s','<a target="_blank" href="%1$s">Get %2$s</a> to unlock these options.' => '<a target="_blank" href="%1$s">Obtén %2$s</a> per desbloquejar aquestes opcions.','Add-on' => 'Complement','View documentation' => 'Veure documentació','Requests require a logged-in WordPress user. Omit user_id to use the current user\'s data, or pass user_id to target another account when the caller can edit that user (edit_user capability). Unauthenticated requests return fc_api_forbidden. An invalid user_id returns fc_api_user_not_found.' => 'Les sol·licituds requereixen un usuari de WordPress que hagi iniciat la sessió. Ometeu user_id per utilitzar les dades de l&#39;usuari actual o passeu user_id per orientar-vos a un altre compte quan la persona que truca pugui editar aquest usuari (capacitat edit_user). Les sol·licituds no autenticades retornen fc_api_forbidden. Un user_id no vàlid retorna fc_api_user_not_found.','HTTP 200 with { "data": { ... } } when the handler returns a payload.' => 'HTTP 200 amb { &quot;data&quot;: { ... } } quan el controlador retorna una càrrega útil.','HTTP 200 with { "success": true } when there is no payload (for example DELETE).' => 'HTTP 200 amb { &quot;success&quot;: true } quan no hi ha cap càrrega útil (per exemple, DELETE).','Failures return WordPress REST error JSON from WP_Error (code, message, data.status). Wire codes use the fc_api_* prefix.' => 'Els errors retornen un error REST de WordPress en format JSON des de WP_Error (code, message, data.status). Els codis de connexió utilitzen el prefix fc_api_*.','Forbidden access.' => 'Accés prohibit.','Target user was not found.' => 'No s&#39;ha trobat l&#39;usuari objectiu.','This feature is not available.' => 'Aquesta funció no està disponible.','A required address field is missing.' => 'Falta un camp d&#39;adreça obligatori.','Postcode or ZIP is invalid.' => 'El codi postal o el codi ZIP no són vàlids.','Phone number is invalid.' => 'El número de telèfon no és vàlid.','State or county is invalid.' => 'L&#39;estat o el comtat no són vàlids.','Country is invalid or has no address fields.' => 'El país no és vàlid o no té camps d&#39;adreça.','The request could not be processed.' => 'No s&#39;ha pogut processar la sol·licitud.','Back to previous step' => 'Torna al pas anterior','Skip to settings' => 'Salta a la configuració','Start over and return to the first guided setup step' => 'Torna a començar i torna al primer pas de configuració guiada','Start over' => 'Torna a començar','Please complete all sub-steps before continuing.' => 'Si us plau, completeu tots els subpassos abans de continuar.','Expand' => 'Expandir','Collapse' => 'Replegar','Skip' => 'Omet','Mark as complete' => 'Marca com a completat','Mark as incomplete' => 'Marca com a incomplet','View full-size image: %s' => 'Veure la imatge a mida completa: %s','Full-size setup guide image' => 'Imatge de la guia de configuració a mida completa','Close image' => 'Tanca la imatge','Fluid Checkout Guided Setup' => 'Configuració guiada de la comprovació de fluids','Welcome' => 'Benvingut/da','Explore your checkout' => 'Explora el teu procés de pagament','All set' => 'Tot a punt','You do not have permission to access this page.' => 'No teniu permís per accedir a aquesta pàgina.','Go to step %1$d: %2$s' => 'Ves al pas %1$d: %2$s','This guided setup helps you get familiar with Fluid Checkout. The steps below are placeholders for now.' => 'Aquesta configuració guiada us ajuda a familiaritzar-vos amb Fluid Checkout. Els passos següents són espais reservats per ara.','Continue to the next step when you are ready.' => 'Continua amb el pas següent quan estiguis a punt.','Open your store checkout to see Fluid Checkout in action.' => 'Obre la caixa de la teva botiga per veure Fluid Checkout en acció.','View checkout page' => 'Veure la pàgina de pagament','You can return to Fluid Checkout settings to continue configuring your store.' => 'Pots tornar a la configuració de Fluid Checkout per continuar configurant la teva botiga.','Review checkout and cart settings' => 'Revisa la configuració de la compra i del carretó','Explore add-ons from the dashboard' => 'Explora els complements des del tauler de control','Finish & go to settings' => 'Finalitza i vés a la configuració','Update the billing phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Actualitza l&#39;opció de visibilitat del camp de telèfon de facturació del valor antic per tal que coincideixi amb les convencions de WooCommerce.','Update the shipping phone field visibility option from the legacy value to match WooCommerce conventions.' => 'Actualitza l&#39;opció de visibilitat del camp de telèfon d&#39;enviament del valor antic per tal que coincideixi amb les convencions de WooCommerce.','Copy the order summary background color setting to the new Split design secondary column background color option.' => 'Copieu la configuració del color de fons del resum de la comanda a la nova opció de color de fons de la columna secundària del disseny dividit.','The enhanced select fields feature is always disabled when using the Biteship plugin.' => 'La funció de camps de selecció millorats sempre està desactivada quan s&#39;utilitza el connector Biteship.','The place order position is always set to "Below the order summary" when using German Market. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'La posició de fer la comanda sempre està definida com a &quot;A sota del resum de la comanda&quot; quan s&#39;utilitza German Market. Aquest complement requereix que el botó de fer la comanda i les caselles de selecció legals es mostrin a sota del resum de la comanda.','The place order position is always set to "Below the order summary" when using Germanized for WooCommerce. That plugin requires the place order button and legal checkboxes to be displayed below the order summary.' => 'La posició de fer la comanda sempre està definida com a &quot;A sota del resum de la comanda&quot; quan s&#39;utilitza Germanized per a WooCommerce. Aquest complement requereix que el botó de fer la comanda i les caselles de selecció legals es mostrin a sota del resum de la comanda.','Edit pickup locations' => 'Edita les ubicacions de recollida','Use local pickup label from WooCommerce settings' => 'Utilitza l&#39;etiqueta de recollida local des de la configuració de WooCommerce','When enabled, the pickup option label on checkout matches the title from WooCommerce pickup location settings. When disabled, the label uses the translatable "Local pickup" text from Fluid Checkout.' => 'Quan està activada, l&#39;etiqueta de l&#39;opció de recollida al moment de la compra coincideix amb el títol de la configuració de la ubicació de recollida de WooCommerce. Quan està desactivada, l&#39;etiqueta utilitza el text traduïble &quot;Recollida local&quot; de Fluid Checkout.','Button label for applying coupon codesApply' => 'Aplicar','Checkout step titleContact' => 'Contacte','Checkout step titleShipping' => 'Enviament','Checkout step titleBilling' => 'Facturació','Checkout step titlePayment' => 'Pagament','Checkout substep change link labelChange' => 'Canviar','Checkout substep save link labelSave changes' => 'Desa els canvis','Substep review textNone.' => 'Cap.','Substep review field format%1$s' => '%1$s','Substep review field format: with label%2$s: %1$s' => '%2$s: %1$s','Image uploader.No image selected.' => 'No s&#39;ha seleccionat cap imatge.','Settings sectionCart' => 'Carro','Settings sectionOrder pay' => 'Ordre de pagament','Settings sectionThank you' => 'Gràcies','Settings section titleIntegrations' => 'Integracions','Settings section titleLicense keys' => 'Claus de llicència','Captcha 